import 'package:flutter/material.dart';

Future<void> showQuickActionsSheet(BuildContext context, {required String title, bool favorite = false, VoidCallback? onFavorite}) => showModalBottomSheet<void>(context: context, backgroundColor: Colors.transparent, builder: (context) => SafeArea(child: Card(child: Padding(padding: const EdgeInsets.all(20), child: Column(mainAxisSize: MainAxisSize.min, children: [ListTile(title: Text(favorite ? 'Remove Favorite' : 'Add Favorite'), leading: const Icon(Icons.favorite_border), onTap: () { onFavorite?.call(); Navigator.pop(context); }), const ListTile(title: Text('Mark Watched / Unwatched'), leading: Icon(Icons.visibility_outlined)), const ListTile(title: Text('Playback Compatibility'), leading: Icon(Icons.tune)), ListTile(title: const Text('Details'), subtitle: Text(title), leading: const Icon(Icons.info_outline))])))));
